  y={k:x[k] for k in ('id','libro','testamento','capitulo','versiculos','paralelos','titulo','title_en','tipo','tags','descripcion')};y.update(url=base+'/',original=base+'.jpg',thumb=base+'-mini.jpg',vertical=base+'-vertical.jpg',medium=base+'-media.jpg',resolution=resolution,weight=f'{source.stat().st_size/1048576:.1f} MB',estado=status,tags_en=[TAGS.get(t,t) for t in x['tags']]);y['cita']=f"{x['libro']} {x['capitulo']}:{x['versiculos']}";y['description_en']=x.get('description_en',f"{x['title_en']}. Bible illustration inspired by {BOOKS.get(x['libro'],x['libro'])} {x['capitulo']}:{x['versiculos']}. Themes: {', '.join(y['tags_en'])}.");items.append(y)
