  schema={'@context':'https://schema.org','@type':'ImageObject','name':x['titulo'],'alternateName':x['title_en'],'description':x['descripcion'],'caption':x['cita'],'contentUrl':'https://verbobiblia.com'+x['original'],'thumbnailUrl':'https://verbobiblia.com'+x['thumb'],'license':'https://verbobiblia.com/imagenes/#licencia','creditText':'Verbo','creator':{'@type':'Organization','name':'Verbo'},'inLanguage':['es','en']}
